-- ===== 0006_admin_users.sql =====
-- 0006_admin_users.sql
-- Multi-admin support: replaces single env-based auth with a managed table.
-- Env vars (ADMIN_USER / ADMIN_PASSWORD / ADMIN_CREDENTIALS) remain a fallback
-- so you can never lock yourself out if this table is empty or corrupted.
--
-- Safe to run multiple times.

set search_path = excel_to_ai, public;

create table if not exists excel_to_ai.admin_users (
  id            uuid primary key default gen_random_uuid(),
  email         text not null unique,
  name          text,
  password_hash text not null,
  is_active     boolean not null default true,
  created_at    timestamptz not null default now(),
  created_by    text,
  last_login_at timestamptz
);

create index if not exists admin_users_email_idx on excel_to_ai.admin_users (lower(email));

-- Service role needs full access (PostgREST will use it server-side).
grant usage on schema excel_to_ai to service_role;
grant all on excel_to_ai.admin_users to service_role;

-- Reload PostgREST schema cache so the table is visible immediately.
notify pgrst, 'reload schema';


-- ===== 0007_otp_telemetry.sql =====
-- 0007_otp_telemetry.sql
-- Adds per-row OTP delivery telemetry and admin-editable OTP help text fields.
-- All columns are nullable / have safe defaults so existing rows are preserved.
-- Safe to run multiple times.

set search_path = excel_to_ai, public;

-- ── registrations: telemetry ────────────────────────────────────────────────
alter table excel_to_ai.registrations
  add column if not exists whatsapp_status text,         -- 'sent' | 'api_failed' | 'skipped' | null (unknown/legacy)
  add column if not exists whatsapp_error  text,         -- Meta API error message if api_failed
  add column if not exists verified_at     timestamptz,  -- set when status flips to Verified
  add column if not exists attempt_number  integer default 1;

create index if not exists registrations_email_phone_idx
  on excel_to_ai.registrations (email, phone);

-- ── settings: OTP help / fallback ──────────────────────────────────────────
alter table excel_to_ai.settings
  add column if not exists otp_help_whatsapp_number text,
  add column if not exists otp_help_text            text,
  add column if not exists otp_resend_label         text;

-- Reload PostgREST schema cache so new columns are visible immediately.
notify pgrst, 'reload schema';


-- ===== 0008_zoom_attendance.sql =====
-- 0008_zoom_attendance.sql
-- Post-webinar attendance tracking. Populated by the admin-triggered
-- "Sync Attendance" action which pulls from Zoom's Reports API and flips
-- these columns + fires Meta CAPI + updates LeadSquared.
--
-- All columns nullable / safe defaults. Idempotent. Safe to run multiple times.

set search_path = excel_to_ai, public;

alter table excel_to_ai.registrations
  add column if not exists attended                  boolean,             -- null = unknown / not synced; true = attended; false = no-show
  add column if not exists attended_at               timestamptz,         -- earliest join time from Zoom report
  add column if not exists attendance_duration_min   integer,             -- total minutes attended (Zoom)
  add column if not exists attendance_synced_at      timestamptz,         -- when we last ran the sync against this row
  add column if not exists meta_attended_event_fired boolean default false; -- idempotency guard so re-running sync doesn't double-fire to Meta

-- Track sync runs across the webinar lifecycle (one row per click of "Sync
-- Attendance" in the admin panel). Useful for audit and for showing the
-- "last synced at" timestamp without scanning every registration row.
create table if not exists excel_to_ai.attendance_sync_runs (
  id            uuid primary key default gen_random_uuid(),
  ran_at        timestamptz not null default now(),
  ran_by        text,                      -- admin email from session
  webinar_id    text,
  attendees_total int,                     -- total participant rows from Zoom
  newly_marked  int,                       -- rows we flipped from null/false to true
  meta_fired    int,                       -- WebinarAttended events sent to Meta CAPI
  lsq_updated   int,                       -- LSQ rows successfully updated
  error_summary text                       -- non-empty if anything went wrong
);

-- Reload PostgREST schema cache so new columns are visible immediately.
notify pgrst, 'reload schema';


-- ===== 0009_webinar_sessions.sql =====
-- 0009_webinar_sessions.sql
-- First-class webinar sessions. Each LP "cohort" (the W001, W002, ... weekly
-- webinars) becomes a row in this table. One is "active" at a time and the
-- LP renders its date/time/Zoom ID instead of values from `settings`.
--
-- Migration steps:
--   1. Create webinar_sessions table
--   2. Add session_id to registrations + attendance_sync_runs
--   3. Seed ONE session from the current live `settings` row so existing data
--      doesn't lose its parent
--   4. Backfill session_id on every existing registration
--
-- Safe to run multiple times.

set search_path = excel_to_ai, public;

create table if not exists excel_to_ai.webinar_sessions (
  id                     uuid primary key default gen_random_uuid(),
  code                   text unique not null,                -- 'W001', 'W002', ... user-defined
  title                  text not null,
  date_label             text,
  time_label             text,
  datetime_utc           timestamptz,
  duration_label         text,
  zoom_webinar_id        text,
  whatsapp_template_name text,
  lsq_source_name        text,
  -- BOTH event tagging strategies are supported (per user choice):
  --   * meta_event_suffix → if set, event names become "Lead_<suffix>" etc.
  --   * Code is always pushed into custom_data.webinar_session_code
  meta_event_suffix      text,
  status                 text not null default 'upcoming' check (status in ('upcoming','active','completed')),
  created_at             timestamptz not null default now(),
  activated_at           timestamptz,
  ended_at               timestamptz,
  -- Cached counters (refreshed by sync attendance, not authoritative).
  registrations_count    int default 0,
  attendees_count        int default 0
);

create unique index if not exists webinar_sessions_one_active_idx
  on excel_to_ai.webinar_sessions (status) where status = 'active';

-- Add session linkage to existing tables.
alter table excel_to_ai.registrations
  add column if not exists session_id uuid references excel_to_ai.webinar_sessions(id);

create index if not exists registrations_session_id_idx
  on excel_to_ai.registrations (session_id);

alter table excel_to_ai.attendance_sync_runs
  add column if not exists session_id uuid references excel_to_ai.webinar_sessions(id);

-- ── Seed: turn the currently-live `settings` row into session "W001" ───────
-- Only inserts if no sessions exist yet (so re-running this migration is a no-op).
do $$
declare
  s record;
  new_session_id uuid;
begin
  if (select count(*) from excel_to_ai.webinar_sessions) = 0 then
    select * into s from excel_to_ai.settings where id = 'speaker';
    insert into excel_to_ai.webinar_sessions (
      code, title, date_label, time_label, datetime_utc, duration_label,
      zoom_webinar_id, whatsapp_template_name, lsq_source_name,
      meta_event_suffix, status, activated_at
    ) values (
      'W001',
      coalesce(s.webinar_title, 'Webinar 1'),
      s.webinar_date_label,
      s.webinar_time_label,
      s.webinar_datetime_utc,   -- already timestamptz (see 0002 migration)
      s.duration_label,
      s.zoom_webinar_id,
      s.whatsapp_template_name,
      s.lsq_source_name,
      'W001',           -- default suffix matches code
      'active',
      now()
    )
    returning id into new_session_id;

    -- Tag every existing registration with this seeded session.
    update excel_to_ai.registrations
       set session_id = new_session_id
     where session_id is null;

    -- Tag past attendance sync runs too.
    update excel_to_ai.attendance_sync_runs
       set session_id = new_session_id
     where session_id is null;
  end if;
end $$;

-- PostgREST reload.
notify pgrst, 'reload schema';


-- ===== 0010_email_campaigns.sql =====
-- 0010_email_campaigns.sql
-- Email campaign management. Each row is one composed campaign (subject + body +
-- audience filter). Status starts as 'draft'; transitions to 'sent' once an email
-- service dispatches it. 'partial' = some recipients failed.

set search_path = excel_to_ai, public;

create table if not exists excel_to_ai.email_campaigns (
  id                uuid primary key default gen_random_uuid(),
  session_id        uuid references excel_to_ai.webinar_sessions(id),
  subject           text not null,
  body_text         text not null,
  -- 'verified' | 'unverified' | 'all'
  audience          text not null check (audience in ('verified','unverified','all')),
  -- 'draft' = saved, no email service yet
  -- 'sending' = in-flight
  -- 'sent'    = fully dispatched
  -- 'partial' = sent to some, failed for others
  -- 'failed'  = dispatch attempted but all failed
  status            text not null default 'draft'
                    check (status in ('draft','sending','sent','partial','failed')),
  total_recipients  int not null default 0,
  sent_count        int not null default 0,
  failed_count      int not null default 0,
  error_summary     text,
  banner_url        text,              -- optional uploaded image shown at top of email
  created_at        timestamptz not null default now(),
  sent_at           timestamptz
);

create index if not exists email_campaigns_session_id_idx
  on excel_to_ai.email_campaigns (session_id);

notify pgrst, 'reload schema';


-- ===== 0011_email_tracking.sql =====
-- 0011_email_tracking.sql
-- Per-event open/click tracking for email campaigns.
-- The tracking pixel at /api/track/open/{campaignId} inserts a row here
-- and increments the denormalised counters on email_campaigns.

set search_path = excel_to_ai, public;

-- Add stats counters to the campaigns table.
alter table excel_to_ai.email_campaigns
  add column if not exists open_count        int not null default 0,
  add column if not exists unique_open_count int not null default 0,
  add column if not exists click_count       int not null default 0;

-- Raw event log (one row per open / click).
create table if not exists excel_to_ai.email_events (
  id             uuid primary key default gen_random_uuid(),
  campaign_id    uuid not null references excel_to_ai.email_campaigns(id) on delete cascade,
  -- 'open'  = tracking pixel fired
  -- 'click' = link click (for future use)
  event_type     text not null check (event_type in ('open','click')),
  -- sha-256 hash of the recipient email — lets us count unique opens
  -- without storing raw PII in this table.
  recipient_hash text,
  url            text,    -- populated for click events
  occurred_at    timestamptz not null default now()
);

create index if not exists email_events_campaign_id_idx
  on excel_to_ai.email_events (campaign_id);

create index if not exists email_events_type_hash_idx
  on excel_to_ai.email_events (campaign_id, event_type, recipient_hash);

notify pgrst, 'reload schema';


