  CREATE POLICY "service role full access" ON excel_to_ai.speaker_submissions
    USING (true) WITH CHECK (true);
EXCEPTION WHEN duplicate_object THEN NULL; END $$;


-- ===== 0027_sync_settings_to_active_session.sql =====
-- 0027_sync_settings_to_active_session.sql
-- The LP prefers the ACTIVE session's speaker/schedule fields over the global
-- settings row (getWebinarConfig), but the admin panel saves edits to the
-- settings row. Before this, admin edits saved fine but never appeared on the
-- live page while a session was active.
--
-- This trigger mirrors any CHANGED settings field onto the active session, so
-- admin edits always reach the live page — for this and every future webinar,
-- independent of app code version. Only columns that actually changed are
-- copied (IS DISTINCT FROM), so e.g. saving a Webinar-tab text field does not
-- clobber a per-session speaker that came from a speaker submission.

CREATE OR REPLACE FUNCTION excel_to_ai.sync_settings_to_active_session()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = excel_to_ai
AS $$
BEGIN
  UPDATE excel_to_ai.webinar_sessions ws SET
    speaker_name    = CASE WHEN NEW.speaker_name         IS DISTINCT FROM OLD.speaker_name         THEN NEW.speaker_name         ELSE ws.speaker_name    END,
    speaker_title   = CASE WHEN NEW.speaker_title        IS DISTINCT FROM OLD.speaker_title        THEN NEW.speaker_title        ELSE ws.speaker_title   END,
    speaker_image   = CASE WHEN NEW.speaker_image        IS DISTINCT FROM OLD.speaker_image        THEN NEW.speaker_image        ELSE ws.speaker_image   END,
    speaker_bio     = CASE WHEN NEW.speaker_bio          IS DISTINCT FROM OLD.speaker_bio          THEN NEW.speaker_bio          ELSE ws.speaker_bio     END,
    date_label      = CASE WHEN NEW.webinar_date_label   IS DISTINCT FROM OLD.webinar_date_label   THEN NEW.webinar_date_label   ELSE ws.date_label      END,
    time_label      = CASE WHEN NEW.webinar_time_label   IS DISTINCT FROM OLD.webinar_time_label   THEN NEW.webinar_time_label   ELSE ws.time_label      END,
    datetime_utc    = CASE WHEN NEW.webinar_datetime_utc IS DISTINCT FROM OLD.webinar_datetime_utc THEN NEW.webinar_datetime_utc ELSE ws.datetime_utc    END,
    duration_label  = CASE WHEN NEW.duration_label       IS DISTINCT FROM OLD.duration_label       THEN NEW.duration_label       ELSE ws.duration_label  END,
    zoom_webinar_id = CASE WHEN NEW.zoom_webinar_id      IS DISTINCT FROM OLD.zoom_webinar_id      THEN NEW.zoom_webinar_id      ELSE ws.zoom_webinar_id END
  WHERE ws.status = 'active';
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_sync_settings_to_active_session ON excel_to_ai.settings;
CREATE TRIGGER trg_sync_settings_to_active_session
AFTER UPDATE ON excel_to_ai.settings
FOR EACH ROW
WHEN (OLD.id = 'speaker')
EXECUTE FUNCTION excel_to_ai.sync_settings_to_active_session();


-- ===== 0027_whatsapp_autosend.sql =====
-- 0027_whatsapp_autosend.sql
-- Event-triggered WhatsApp automations (mirrors the email auto-send model):
--   • unverified → nudge people who filled the form but didn't complete OTP
--   • verified   → welcome / join-link right after OTP
--   • noshow     → follow-up to registrants who didn't attend
-- An auto-send config is a whatsapp_campaign flagged auto_send_enabled with a
-- trigger + delay. When a trigger fires we enqueue a per-recipient scheduled
-- send; a cron sends due ones (skipping anyone whose state changed, e.g. they
-- verified before the nudge fired).

ALTER TABLE excel_to_ai.whatsapp_campaigns
  ADD COLUMN IF NOT EXISTS auto_send_enabled boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS auto_send_trigger text
    CHECK (auto_send_trigger IN ('unverified','verified','noshow')),
  ADD COLUMN IF NOT EXISTS delay_value int NOT NULL DEFAULT 15,
  ADD COLUMN IF NOT EXISTS delay_unit text NOT NULL DEFAULT 'minutes'
    CHECK (delay_unit IN ('minutes','hours','days'));

CREATE TABLE IF NOT EXISTS excel_to_ai.whatsapp_scheduled_sends (
  id              uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  campaign_id     uuid        NOT NULL REFERENCES excel_to_ai.whatsapp_campaigns(id) ON DELETE CASCADE,
  registration_id text,
  phone           text        NOT NULL,
  recipient_name  text        NOT NULL DEFAULT '',
  trigger         text        NOT NULL CHECK (trigger IN ('unverified','verified','noshow')),
  send_after      timestamptz NOT NULL,
  status          text        NOT NULL DEFAULT 'pending'
                    CHECK (status IN ('pending','sent','skipped','cancelled','failed')),
  error           text,
  created_at      timestamptz NOT NULL DEFAULT now(),
  processed_at    timestamptz
);

-- Due-work lookup, and a way to cancel a person's pending nudge when they verify.
CREATE INDEX IF NOT EXISTS wss_due ON excel_to_ai.whatsapp_scheduled_sends (send_after) WHERE status = 'pending';
CREATE INDEX IF NOT EXISTS wss_reg ON excel_to_ai.whatsapp_scheduled_sends (registration_id, trigger) WHERE status = 'pending';

ALTER TABLE excel_to_ai.whatsapp_scheduled_sends ENABLE ROW LEVEL SECURITY;
DO $$ BEGIN
  CREATE POLICY "service role full access" ON excel_to_ai.whatsapp_scheduled_sends
    USING (true) WITH CHECK (true);
EXCEPTION WHEN duplicate_object THEN NULL; END $$;


-- ===== 0028_whatsapp_campaign_conversion.sql =====
-- 0028_whatsapp_campaign_conversion.sql
-- Per-campaign "unverified → verified" conversion.
--
-- For a campaign that reached unverified people (audience 'unverified' or 'all'),
-- counts how many recipients we actually reached and, of those who were NOT
-- already verified before the send, how many have since completed OTP.
--
-- Attribution rule: a verification counts only when verified_at >= the campaign's
-- sent_at (they verified AFTER receiving it). Recipients already verified before
-- the send are excluded from the denominator so the rate reflects the unverified
-- audience only. The join is an exact phone match — whatsapp_send_log.phone is the
-- unmodified registrations.phone the recipient was built from.
create or replace function excel_to_ai.whatsapp_campaign_conversion(p_campaign_id uuid)
returns table (reached int, unverified_reached int, verified_after int)
language sql
security definer
as $$
  with camp as (
    select sent_at from excel_to_ai.whatsapp_campaigns where id = p_campaign_id
  ),
  -- Distinct phones the campaign actually delivered a message to.
  reached_phones as (
    select distinct l.phone
    from excel_to_ai.whatsapp_send_log l
    where l.campaign_id = p_campaign_id
      and l.status in ('sent', 'delivered', 'read')
  ),
  -- Collapse the (possibly multiple) registration rows per phone into one verdict.
  per_phone as (
    select
      rp.phone,
      bool_or(r.status = 'Verified' and r.verified_at >= (select sent_at from camp)) as verified_after,
      bool_or(r.status = 'Verified' and r.verified_at <  (select sent_at from camp)) as verified_before
    from reached_phones rp
    left join excel_to_ai.registrations r on r.phone = rp.phone
    group by rp.phone
  )
  select
    (select count(*) from reached_phones)::int                                  as reached,
    (select count(*) from per_phone where not coalesce(verified_before, false))::int as unverified_reached,
    (select count(*) from per_phone where coalesce(verified_after, false))::int      as verified_after;
$$;

grant execute on function excel_to_ai.whatsapp_campaign_conversion(uuid)
  to service_role, authenticated, anon;

notify pgrst, 'reload schema';


-- ===== 0029_whatsapp_campaign_converted_phones.sql =====
-- 0029_whatsapp_campaign_converted_phones.sql
-- Companion to 0028's conversion COUNT: returns the actual phone numbers behind
-- the "verified_after" figure, so the recipients list can flag exactly WHO went
-- from unverified → verified after receiving a campaign.
--
-- Same attribution as 0028: a reached recipient (sent/delivered/read) whose
-- registration is now Verified with verified_at >= the campaign's sent_at. The
-- count of these rows equals whatsapp_campaign_conversion().verified_after.
create or replace function excel_to_ai.whatsapp_campaign_converted_phones(p_campaign_id uuid)
returns table (phone text)
language sql
security definer
as $$
  with camp as (
    select sent_at from excel_to_ai.whatsapp_campaigns where id = p_campaign_id
  ),
  reached_phones as (
    select distinct l.phone
    from excel_to_ai.whatsapp_send_log l
    where l.campaign_id = p_campaign_id
      and l.status in ('sent', 'delivered', 'read')
  )
  select rp.phone
  from reached_phones rp
  where exists (
    select 1
    from excel_to_ai.registrations r
    where r.phone = rp.phone
      and r.status = 'Verified'
      and r.verified_at >= (select sent_at from camp)
  );
$$;

grant execute on function excel_to_ai.whatsapp_campaign_converted_phones(uuid)
  to service_role, authenticated, anon;

notify pgrst, 'reload schema';


-- ===== 0030_otp_message_id.sql =====
-- 0030_otp_message_id.sql
-- Adds whatsapp_message_id to registrations so OTP sends can be correlated to
-- Meta's delivery-status webhook (delivered / read / FAILED). Before this, OTP
-- delivery failures were invisible: the send API returns 200 ("accepted") even
-- when Meta later drops the message, and the webhook had nowhere to record it.
--
-- Nullable, no default — existing rows are preserved. Safe to run multiple times.

set search_path = excel_to_ai, public;

alter table excel_to_ai.registrations
  add column if not exists whatsapp_message_id text;   -- Meta wamid from the OTP send

-- The webhook looks rows up by this id, so index it.
create index if not exists registrations_whatsapp_message_id_idx
  on excel_to_ai.registrations (whatsapp_message_id);

-- Reload PostgREST schema cache so the new column is visible to the REST API
-- immediately (the app reads/writes registrations via supabase-js / PostgREST).
notify pgrst, 'reload schema';


-- ===== 0031_session_otp_required.sql =====
-- 0031_session_otp_required.sql
-- Per-session toggle for whether the registration form requires WhatsApp OTP
-- verification. Added to work around WhatsApp delivery outages: an admin can
-- turn OTP off for the active session so registrations still complete (Zoom
-- registration + verified emails) without a code.
--
-- Defaults to TRUE so existing behaviour is unchanged. Safe to run repeatedly.

set search_path = excel_to_ai, public;

alter table excel_to_ai.webinar_sessions
  add column if not exists otp_required boolean not null default true;

-- Reload PostgREST schema cache so the new column is visible to the REST API
-- immediately.
notify pgrst, 'reload schema';


-- ===== 0032_registration_current_status.sql =====
-- 0032_registration_current_status.sql
-- The registration form has always had a MANDATORY "current status" select
-- (Student / Recent graduate / Working professional). Its value was validated
-- client-side, posted to /api/lead/capture as `body.status` … and then dropped:
-- nothing read it, so it reached neither this table nor LeadSquared. Sales had
-- no way to segment by it.
--
-- Named current_status, NOT status: registrations.status already means the OTP
-- state ('Verified' / 'Unverified'), and reusing the name would collide.

ALTER TABLE excel_to_ai.registrations
  ADD COLUMN IF NOT EXISTS current_status text;

-- Segmentation queries filter on it, and the admin list groups by it.
CREATE INDEX IF NOT EXISTS registrations_current_status
  ON excel_to_ai.registrations (current_status)
  WHERE current_status IS NOT NULL;


-- ===== 0033_whatsapp_webinar_reminders.sql =====
-- 0033_whatsapp_webinar_reminders.sql
-- Time-based WhatsApp reminders before the webinar.
--
-- WHY: reminders were email-only, and email open rate is ~2% — so roughly 145
-- of the last 149 registrants never saw one. WhatsApp is the channel these
-- registrants actually read (it is already how OTP reaches them).
--
-- The existing auto-send triggers are all EVENT-driven (fire N minutes after
-- something happens). Reminders are CLOCK-driven: they fire at a fixed offset
-- before the session's datetime_utc, so the send time is computed from the
-- webinar, not from the enqueue moment. Everything else — the scheduled-sends
-- table, the 5-minute drain cron, templates, opt-outs — is reused as-is.
--
-- "On registration" deliberately gets NO new trigger: the existing 'verified'
-- automation already fires right after OTP, which is that moment.

ALTER TABLE excel_to_ai.whatsapp_campaigns
  DROP CONSTRAINT IF EXISTS whatsapp_campaigns_auto_send_trigger_check;
ALTER TABLE excel_to_ai.whatsapp_campaigns
  ADD CONSTRAINT whatsapp_campaigns_auto_send_trigger_check
  CHECK (auto_send_trigger IN (
    'unverified','verified','noshow',
    'reminder_t3d','reminder_t1d','reminder_t1h'
  ));

ALTER TABLE excel_to_ai.whatsapp_scheduled_sends
  DROP CONSTRAINT IF EXISTS whatsapp_scheduled_sends_trigger_check;
ALTER TABLE excel_to_ai.whatsapp_scheduled_sends
  ADD CONSTRAINT whatsapp_scheduled_sends_trigger_check
  CHECK (trigger IN (
    'unverified','verified','noshow',
    'reminder_t3d','reminder_t1d','reminder_t1h'
  ));

-- One reminder per person per trigger per session. Without this, a repeat
-- verification (or a retried request) would enqueue a second copy and the
-- registrant would get the same reminder twice.
CREATE UNIQUE INDEX IF NOT EXISTS wss_one_reminder_per_reg
  ON excel_to_ai.whatsapp_scheduled_sends (registration_id, trigger)
  -- Listed explicitly rather than LIKE 'reminder_%': '_' is a single-character
  -- wildcard in LIKE, so that pattern would also match unrelated future values.
  WHERE registration_id IS NOT NULL
    AND trigger IN ('reminder_t3d', 'reminder_t1d', 'reminder_t1h');


-- ===== 0034_email_campaign_schedule.sql =====
-- 0034_email_campaign_schedule.sql
-- One-off SCHEDULED email broadcasts ("send this blast Tuesday 9am").
--
-- WhatsApp campaigns already have this (0023): scheduled_for + a 'scheduled'
-- status, fired by the 5-minute cron. Email had only the per-recipient
-- email_schedule_queue used by trigger-based auto-sends, so a campaign-level
-- send could only be fired by hand, right now. This brings email to parity.

ALTER TABLE excel_to_ai.email_campaigns
  ADD COLUMN IF NOT EXISTS scheduled_for timestamptz;

-- Allow 'scheduled' alongside the existing statuses.
ALTER TABLE excel_to_ai.email_campaigns
  DROP CONSTRAINT IF EXISTS email_campaigns_status_check;
ALTER TABLE excel_to_ai.email_campaigns
  ADD CONSTRAINT email_campaigns_status_check
  CHECK (status IN ('draft','scheduled','sending','sent','partial','failed'));

-- Due-work lookup for the cron. Partial index: only scheduled rows are polled.
CREATE INDEX IF NOT EXISTS ec_scheduled_due
  ON excel_to_ai.email_campaigns (scheduled_for)
  WHERE status = 'scheduled';


-- ===== 0035_session_audit_log.sql =====
-- 0035_session_audit_log.sql
-- Who changed a webinar session, when, and what actually changed.
--
-- Added after otp_required was found flipped off on the live launch session
-- for ~3 hours with no way to tell who did it or why — the PATCH route wrote
-- the column but logged nothing. Generic by design (activate / end / update),
-- not otp_required-specific, so it covers the next unexplained flip too,
-- whatever field it's on.
--
-- Safe to run repeatedly.

set search_path = excel_to_ai, public;

create table if not exists excel_to_ai.session_audit_log (
  id            uuid primary key default gen_random_uuid(),
  created_at    timestamptz not null default now(),
  session_id    uuid not null references excel_to_ai.webinar_sessions(id) on delete cascade,
  admin_email   text not null,
  action        text not null,              -- 'activate' | 'end' | 'update'
  changes       jsonb not null default '{}', -- { field: { from, to }, ... } — only fields that actually changed
  ip            text
);

create index if not exists session_audit_log_session_idx on excel_to_ai.session_audit_log (session_id, created_at desc);

-- Service role needs full access (PostgREST will use it server-side).
grant usage on schema excel_to_ai to service_role;
grant all on excel_to_ai.session_audit_log to service_role;

notify pgrst, 'reload schema';


-- ===== 0036_broadcast_audience_scope.sql =====
-- 0036_broadcast_audience_scope.sql
-- Lets a broadcast reach everyone who EVER registered — across every past
-- masterclass — instead of only the active session's registrants.
--
-- audience_scope
--   'session'      — the active session's registrants (every campaign until now)
--   'all_sessions' — one row per person across all sessions; "verified" means
--                    they verified in ANY session, "unverified" means never
--
-- exclude_session_registrants
--   Only meaningful with 'all_sessions'. Drops anyone who already has a
--   registration in the campaign's own session — the masterclass being
--   promoted — so a "register for the new masterclass" message never reaches
--   someone who already did.
--
-- Both are stored on the campaign rather than passed per request because a
-- campaign's audience is RECOMPUTED later — when a scheduled send fires, and on
-- "Send to new" / "Retry". Without the scope persisted, those would silently
-- shrink a 6,000-person broadcast back to the active session's few hundred.
--
-- Defaults keep every existing campaign exactly as it was. Safe to re-run.

set search_path = excel_to_ai, public;

alter table excel_to_ai.whatsapp_campaigns
  add column if not exists audience_scope text not null default 'session'
    check (audience_scope in ('session', 'all_sessions')),
  add column if not exists exclude_session_registrants boolean not null default false;

alter table excel_to_ai.email_campaigns
  add column if not exists audience_scope text not null default 'session'
    check (audience_scope in ('session', 'all_sessions')),
  add column if not exists exclude_session_registrants boolean not null default false;

notify pgrst, 'reload schema';


-- ===== 0037_broadcast_attendance_audiences.sql =====
-- 0037_broadcast_attendance_audiences.sql
-- Adds two broadcast audiences, built from Zoom attendance across every
-- masterclass (used with audience_scope = 'all_sessions'):
--
--   never_attended   — registered (verified or not), never attended any session
--   verified_no_show — verified at least once, never attended any session
--
-- The audience column's CHECK constraint only allowed verified/unverified/all,
-- so saving a campaign with a new audience would fail. This widens it on both
-- campaign tables. Existing rows are untouched. Safe to re-run.

set search_path = excel_to_ai, public;

-- Drop whatever CHECK constraint currently guards each table's audience column
-- (normally <table>_audience_check, but don't rely on the name), then add ours.
do $$
declare r record;
begin
  for r in
    select c.conrelid::regclass as tbl, c.conname
    from pg_constraint c
    join pg_attribute a on a.attrelid = c.conrelid and a.attnum = any (c.conkey)
    where c.contype = 'c'
      and a.attname = 'audience'
      and c.conrelid in ('excel_to_ai.whatsapp_campaigns'::regclass, 'excel_to_ai.email_campaigns'::regclass)
  loop
    execute format('alter table %s drop constraint %I', r.tbl, r.conname);
  end loop;
end $$;

alter table excel_to_ai.whatsapp_campaigns
  add constraint whatsapp_campaigns_audience_check
    check (audience in ('verified', 'unverified', 'all', 'never_attended', 'verified_no_show'));

alter table excel_to_ai.email_campaigns
  add constraint email_campaigns_audience_check
    check (audience in ('verified', 'unverified', 'all', 'never_attended', 'verified_no_show'));

notify pgrst, 'reload schema';


-- ===== 0038_whatsapp_queue_atomic_claim.sql =====
-- 0038_whatsapp_queue_atomic_claim.sql
-- Stop concurrent queue drains from sending the same person twice.
--
-- Before: claimPendingWhatsAppQueue() was a plain SELECT of 'pending' rows, and rows were only
-- marked after the whole chunk had been sent (tens of seconds later). The cron (every 5 min), the
-- inline send request and any overlapping cron tick could all read the SAME pending rows and message
-- the same people again — the 11-13 log shows 937 'sent' rows for 719 unique phones, and ~6,600
-- failed rows for ~4,060 unique failed people.
--
-- Now: claiming flips rows to 'processing' in one statement, using FOR UPDATE SKIP LOCKED, so two
-- drains can never receive the same row. Rows stuck in 'processing' (function killed mid-send) are
-- returned to 'pending' after 15 minutes.

alter table excel_to_ai.whatsapp_send_queue
  add column if not exists claimed_at timestamptz;

alter table excel_to_ai.whatsapp_send_queue
  drop constraint if exists whatsapp_send_queue_status_check;
alter table excel_to_ai.whatsapp_send_queue
  add constraint whatsapp_send_queue_status_check
  check (status in ('pending', 'processing', 'sent', 'failed', 'skipped', 'cancelled'));

create or replace function excel_to_ai.claim_whatsapp_queue(p_campaign_id uuid, p_limit int)
returns table (id uuid, phone text, recipient_name text)
language plpgsql
security definer
as $$
begin
  -- Recover rows abandoned by a drain that died mid-send.
  update excel_to_ai.whatsapp_send_queue q
     set status = 'pending'
   where q.campaign_id = p_campaign_id
     and q.status = 'processing'
     and q.processed_at is null
     and q.claimed_at < now() - interval '15 minutes';

  return query
  with picked as (
    select q.id
      from excel_to_ai.whatsapp_send_queue q
     where q.campaign_id = p_campaign_id
       and q.status = 'pending'
     order by q.created_at
     limit greatest(p_limit, 0)
     for update skip locked
  )
  update excel_to_ai.whatsapp_send_queue q
     set status = 'processing', claimed_at = now()
    from picked
   where q.id = picked.id
  returning q.id, q.phone, q.recipient_name;
end;
$$;

-- "Which campaigns still have work" must count rows in flight as work too.
create index if not exists wsq_processing
  on excel_to_ai.whatsapp_send_queue (campaign_id)
  where status = 'processing';


-- ===== 0039_whatsapp_aggregates.sql =====
-- 0039_whatsapp_aggregates.sql
-- Count in the database instead of shipping every log row to the app.
--
-- Why: the free plan allows 5 GB of egress a month and the old project used 13-14 GB and was
-- shut off. Every queue drain (the cron every 5 min, plus the admin page asking every 2 s while
-- a campaign was "sending") downloaded the campaign's ENTIRE send log — 10,000+ rows, several MB —
-- just to compute three counts, and again for the failure breakdown and the daily-limit check.
-- These functions return a handful of numbers instead.

create index if not exists whatsapp_send_log_sent_at_idx
  on excel_to_ai.whatsapp_send_log (sent_at);

-- Deduped per phone (last 10 digits), keeping each person's furthest-along status.
create or replace function excel_to_ai.whatsapp_campaign_log_counts(p_campaign_id uuid)
returns table (sent int, failed int, skipped int)
language sql stable security definer set search_path = excel_to_ai, public
as $$
  with best as (
    select coalesce(nullif(right(regexp_replace(phone, '\D', '', 'g'), 10), ''), id::text) as k,
           max(case status when 'read' then 4 when 'delivered' then 3 when 'sent' then 2
                           when 'failed' then 1 else 0 end) as r
      from whatsapp_send_log
     where campaign_id = p_campaign_id
     group by 1
  )
  select (count(*) filter (where r >= 2))::int,
         (count(*) filter (where r = 1))::int,
         (count(*) filter (where r = 0))::int
    from best;
$$;

-- Unique people successfully messaged since p_since (the daily-limit check).
create or replace function excel_to_ai.whatsapp_daily_sent_count(p_since timestamptz)
returns int
language sql stable security definer set search_path = excel_to_ai, public
as $$
  select count(distinct right(regexp_replace(phone, '\D', '', 'g'), 10))::int
    from whatsapp_send_log
   where status in ('sent', 'delivered', 'read')
     and sent_at >= p_since;
$$;

-- People whose best status is 'failed', grouped by their latest error (code, or text when no code).
create or replace function excel_to_ai.whatsapp_failure_groups(p_campaign_id uuid)
returns table (error_key text, sample text, people int)
language sql stable security definer set search_path = excel_to_ai, public
as $$
  with per as (
    select right(regexp_replace(phone, '\D', '', 'g'), 10) as k,
           max(case status when 'read' then 4 when 'delivered' then 3 when 'sent' then 2
                           when 'failed' then 1 else 0 end) as r,
           (array_agg(error_detail order by sent_at desc) filter (where status = 'failed'))[1] as err
      from whatsapp_send_log
     where campaign_id = p_campaign_id
     group by 1
  )
  select coalesce(substring(err from 'code=(\d+)'), left(coalesce(err, ''), 80)) as error_key,
         min(err) as sample,
         count(*)::int as people
    from per
   where r = 1 and k <> ''
   group by 1
   order by 3 desc
   limit 50;
$$;

grant execute on function excel_to_ai.whatsapp_campaign_log_counts(uuid) to service_role;
grant execute on function excel_to_ai.whatsapp_daily_sent_count(timestamptz) to service_role;
grant execute on function excel_to_ai.whatsapp_failure_groups(uuid) to service_role;
grant execute on function excel_to_ai.claim_whatsapp_queue(uuid, int) to service_role;


-- ===== 0040_service_role_grants.sql =====
-- 0040_service_role_grants.sql
-- The app's server code talks to Supabase with the SECRET key, i.e. as `service_role`. No earlier
-- migration granted that role anything on excel_to_ai — on the original project the grants were
-- added by hand, so a fresh project (Nov 2026 move) got "permission denied" on 16 of 20 tables.
-- Only service_role is granted; anon/authenticated (the public key) get nothing new.

grant usage on schema excel_to_ai to service_role;
grant all on all tables    in schema excel_to_ai to service_role;
grant all on all sequences in schema excel_to_ai to service_role;
grant execute on all functions in schema excel_to_ai to service_role;

-- Tables/functions created by later migrations (run as postgres) get the same automatically.
alter default privileges for role postgres in schema excel_to_ai grant all on tables    to service_role;
alter default privileges for role postgres in schema excel_to_ai grant all on sequences to service_role;
alter default privileges for role postgres in schema excel_to_ai grant execute on functions to service_role;


-- ===== 0041_session_wa_creatives.sql =====
alter table excel_to_ai.webinar_sessions
  add column if not exists wa_creatives jsonb not null default '{}'::jsonb;
alter table excel_to_ai.webinar_sessions
  add column if not exists wa_creatives_sync jsonb;

commit;
